function survives(cell: Cell, liveCells: Cell[]): boolean {
  return countNeighbors(cell, liveCells) === 2;
}

function isBorn(cell: Cell, liveCells: Cell[]): boolean {
  return !isAlive(cell, liveCells) && countNeighbors(cell, liveCells) === 3;
}

function birthCandidates(liveCells: Cell[]): Cell[] {
  return uniqueCells(liveCells.flatMap(neighborsOf));
}

export function nextGeneration(liveCells: Cell[]): Cell[] {
  const survivors = liveCells.filter((cell) => survives(cell, liveCells));
  const births = birthCandidates(liveCells).filter((cell) =>
    isBorn(cell, liveCells)
  );
  return [...survivors, ...births];
}
